BEGIN;
DO $$
BEGIN
 IF current_database()<>'openlocal_demo' OR (SELECT shobj_description(oid,'pg_database') FROM pg_database WHERE datname=current_database()) IS DISTINCT FROM 'openlocal-demo-v1-local-only' THEN RAISE EXCEPTION 'Not a demo database'; END IF;
 IF (SELECT count(*) FROM businesses WHERE slug IN ('demo-tienda','demo-pan','demo-salon'))<>3 THEN RAISE EXCEPTION 'Missing demo businesses'; END IF;
 IF EXISTS(SELECT 1 FROM stock_levels sl JOIN businesses b ON b.id=sl.business_id LEFT JOIN (SELECT business_id,variant_id,location_id,sum(CASE WHEN movement_type LIKE 'IN_%' THEN quantity ELSE -quantity END) q FROM stock_movements GROUP BY 1,2,3) m USING(business_id,variant_id,location_id) WHERE b.slug LIKE 'demo-%' AND (m.q IS NULL OR sl.quantity_on_hand<>m.q OR sl.quantity_on_hand<0)) THEN RAISE EXCEPTION 'Stock ledger mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM stock_movements m JOIN businesses b ON b.id=m.business_id WHERE b.slug IN ('demo-tienda','demo-pan') AND NOT EXISTS(SELECT 1 FROM stock_levels sl WHERE sl.business_id=m.business_id AND sl.variant_id=m.variant_id AND sl.location_id=m.location_id)) THEN RAISE EXCEPTION 'Ledger missing stock level'; END IF;
 IF EXISTS(SELECT 1 FROM preorders p JOIN businesses b ON b.id=p.business_id WHERE b.slug='demo-pan' AND p.estimated_total<>(SELECT sum(total) FROM preorder_items WHERE preorder_id=p.id)) THEN RAISE EXCEPTION 'Preorder totals mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM appointments a JOIN appointments b ON a.business_id=b.business_id AND a.resource_id=b.resource_id AND a.id<b.id AND a.status IN ('requested','confirmed') AND b.status IN ('requested','confirmed') AND tstzrange(a.starts_at,a.ends_at+make_interval(mins=>a.buffer_minutes)) && tstzrange(b.starts_at,b.ends_at+make_interval(mins=>b.buffer_minutes))) THEN RAISE EXCEPTION 'Appointment overlap'; END IF;
 IF EXISTS(SELECT 1 FROM product_variants v JOIN businesses b ON b.id=v.business_id WHERE b.slug='demo-tienda' AND NOT EXISTS(SELECT 1 FROM stock_movements m WHERE m.variant_id=v.id AND m.movement_type='OUT_SALE' AND m.created_at>=now()-interval '90 days')) THEN RAISE EXCEPTION 'EOQ demand missing'; END IF;
 IF EXISTS(SELECT 1 FROM (SELECT id,business_id,status FROM preorders UNION ALL SELECT id,business_id,status FROM appointments) r JOIN businesses b ON b.id=r.business_id WHERE b.slug IN ('demo-pan','demo-salon') AND r.status IS DISTINCT FROM (SELECT to_status FROM request_history h WHERE coalesce(h.appointment_id,h.preorder_id)=r.id ORDER BY at DESC,id DESC LIMIT 1)) THEN RAISE EXCEPTION 'Request history mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM (SELECT id,business_id,confirmed_at FROM preorders UNION ALL SELECT id,business_id,confirmed_at FROM appointments) r JOIN businesses b ON b.id=r.business_id WHERE b.slug IN ('demo-pan','demo-salon') AND (r.confirmed_at IS NOT NULL) IS DISTINCT FROM EXISTS(SELECT 1 FROM module_usage_events u JOIN business_subscriptions s USING(business_id) WHERE u.record_id=r.id AND u.period_start=s.period_start AND u.created_at>=s.period_start AND u.created_at<s.period_end)) THEN RAISE EXCEPTION 'Quota usage mismatch'; END IF;
 IF (SELECT count(DISTINCT class) FROM (WITH v AS (SELECT p.id,sum(sales_revenue) AS value FROM products p JOIN businesses b ON b.id=p.business_id JOIN product_sales_summary s ON s.product_id=p.id WHERE b.slug='demo-tienda' GROUP BY p.id), r AS (SELECT sum(value) OVER (ORDER BY value DESC,id)/sum(value) OVER () ratio FROM v) SELECT CASE WHEN ratio<=.8 THEN 'A' WHEN ratio<=.95 THEN 'B' ELSE 'C' END class FROM r) abc)<>3 THEN RAISE EXCEPTION 'ABC needs all three classes'; END IF;
END $$;
SELECT b.slug,count(DISTINCT p.id) AS products,count(DISTINCT m.id) AS movements FROM businesses b LEFT JOIN products p ON p.business_id=b.id LEFT JOIN stock_movements m ON m.business_id=b.id WHERE b.slug IN ('demo-tienda','demo-pan','demo-salon') GROUP BY b.slug ORDER BY b.slug;
SELECT 'Ledger, totals, appointment conflicts, request history, quota, EOQ and ABC checks passed';
ROLLBACK;
